RE_MEDIA = {
    "youtube": re.compile(
        r"https://(?:youtu\.be/|www\.youtube\.com/.+?v=)([0-9A-Za-z_-]{11})"
    ),
    "kinopoisk": re.compile(r"https://hd\.kinopoisk\.ru/.*([0-9a-z]{32})"),
    "strm": re.compile(r"https://yandex.ru/efir\?.*stream_id=([^&]+)"),
