        r"(https?://ok\.ru/video/\d+|https?://vk.com/video-?[0-9_]+)"
    ),
    "vk": re.compile(r"https://vk\.com/.*(video-?[0-9_]+)"),
    "bookmate": re.compile(r"https://books\.yandex\.ru/audiobooks/(\w+)"),
}


async def get_media_payload(session: YandexSession, media_id: str) -> dict | None:
    for k, v in RE_MEDIA.items():
        if m := v.search(media_id):
            if k in ("youtube", "kinopoisk", "strm", "yavideo"):
                return play_video_by_descriptor(k, m[1])

            elif k == "vk":
                url = f"https://vk.com/{m[1]}"
                return play_video_by_descriptor("yavideo", url)

            elif k == "music.yandex.playlist":
                if uid := await get_playlist_uid(session, m[1], m[2]):
                    return {
                        "command": "playMusic",
                        "type": "playlist",
                        "id": f"{uid}:{m[2]}",
                    }

            elif k == "music.yandex":
                return {
                    "command": "playMusic",
                    "type": m[1],
                    "id": m[2],
                }

            elif k == "kinopoisk.id":
                try:
                    r = await session.get(
                        "https://ott-widget.kinopoisk.ru/ott/api/kp-film-status/",
                        params={"kpFilmId": m[1]},
                    )
                    resp = await r.json()
                    return play_video_by_descriptor("kinopoisk", resp["uuid"])

                except:
                    return None

            elif k == "bookmate":
                try:
                    r = await session.post(
                        "https://api-gateway-rest.bookmate.yandex.net/audiobook/album",
                        json={"audiobook_uuid": m[1]},
                    )
                    resp = await r.json()
                    return {
                        "command": "playMusic",
                        "type": "album",
                        "id": resp["album_id"],
                    }
                except:
                    return None

    return None


def audio_play_command(url: str, ext: str, metadata: dict = None) -> dict:
    """Play any URL via the `audio_play` directive - the same one Yandex cloud
    uses for music. Station firmware since ~July 2026 ignores the payload of the
    legacy `radio_play` directive and falls back to a random Yandex radio.

    Station detects the codec from the content, so `format` only has to be a
    valid enum value: HLS for playlists and MP3 for everything else (verified
    with real aac/flac/wav files). An unknown value makes the station drop the
    directive without a single request to the URL.
    """
    hls = ext == "m3u8"
    # `Track` gives a progress bar and artist, `FmRadio` - a radio UI
    payload = {
        "stream": {
            "url": url,
            "format": "HLS" if hls else "MP3",
            "type": "FmRadio" if hls else "Track",
            # "offset_ms": 0,
            # "duration_ms": 2147483647,
        },
        "metadata": {},
        # "set_pause": False,
    }
    if metadata:
        if stream_id := metadata.get("id"):
            payload["stream"]["id"] = stream_id
        if title := metadata.get("title"):
            payload["metadata"]["title"] = title
        if subtitle := metadata.get("artist"):
            payload["metadata"]["subtitle"] = subtitle
        if image := metadata.get("imageUrl"):
            payload["metadata"]["art_image_url"] = image

    return external_command("audio_play", payload)


def get_stream_url(
    media_id: str, ext: str | None, metadata: dict = None
) -> dict | None:
    if ext in ("aac", "flac", "m3u8", "mp3", "mp4", "wav"):
        # station can't handle links without extension
        stream_url = stream.get_url(media_id, ext, 3)
        return audio_play_command(stream_url, ext, metadata)

    if ext == "gif":
        # maximum link size ~250 symbols
        if media_id[0] == "/":
            media_id = stream.get_url(media_id, ext, 0)
        payload = {"animation_sequence": [{"frontal_led_image": media_id}]}
        return external_command("draw_led_screen", payload)

    return None


def external_command(name: str, payload: dict | str = None) -> dict:
    data = {1: name}
    if payload:
        data[2] = json.dumps(payload) if isinstance(payload, dict) else payload
    return {
        "command": "externalCommandBypass",
        "data": base64.b64encode(protobuf.dumps(data)).decode(),
    }


def draw_animation_command(data: str) -> dict:
    payload = {
